  2→//!
  3→//! This module handles loading environment variables from various sources
  4→//! and detecting sensitive values that should be masked in output.
  5→
  6→use crate::error::{BivvyError, Result};
  7→use std::collections::HashMap;
  8→use std::fs;
  9→use std::path::Path;
 10→
 11→/// Built-in secret patterns that are always masked.
 12→///
 13→/// These patterns use simple glob-style matching where `*` matches
 14→/// any characters.
 15→pub const SECRET_PATTERNS: &[&str] = &[
 16→    "*_KEY",
 17→    "*_SECRET",
 18→    "*_TOKEN",
 19→    "*_PASSWORD",
 20→    "*_CREDENTIAL",
 21→    "API_KEY",
 22→    "SECRET_KEY",
 23→    "ACCESS_TOKEN",
 24→    "AUTH_TOKEN",
 25→    "DATABASE_URL",
 26→    "REDIS_URL",
 27→    "AWS_*",
 28→    "GITHUB_TOKEN",
 29→    "OPENAI_API_KEY",
 30→];
 31→
 32→/// Load environment variables from system.
 33→pub fn load_system_env() -> HashMap<String, String> {
 34→    std::env::vars().collect()
 35→}
 36→
 37→/// Load environment variables from a dotenv-style file.
 38→///
 39→/// # Format
 40→///
 41→/// ```text
 42→/// # Comment
 43→/// KEY=value
 44→/// QUOTED="value with spaces"
 45→/// SINGLE='also works'
 46→/// ```
 47→///
 48→/// # Errors
 49→///
 50→/// Returns `ConfigNotFound` if the file doesn't exist.
 51→/// Returns `ConfigParseError` for invalid lines.
 52→pub fn load_env_file(path: &Path) -> Result<HashMap<String, String>> {
 53→    let content = fs::read_to_string(path).map_err(|e| {
 54→        if e.kind() == std::io::ErrorKind::NotFound {
 55→            BivvyError::ConfigNotFound {
 56→                path: path.to_path_buf(),
 57→            }
 58→        } else {
 59→            BivvyError::Io(e)
 60→        }
 61→    })?;
 62→
 63→    parse_dotenv(&content, path)
 64→}
 65→
 66→/// Load env file if it exists, return empty map otherwise.
 67→pub fn load_env_file_optional(path: &Path) -> HashMap<String, String> {
 68→    load_env_file(path).unwrap_or_default()
 69→}
 70→
 71→/// Parse dotenv-style content.
 72→fn parse_dotenv(content: &str, source_path: &Path) -> Result<HashMap<String, String>> {
 73→    let mut env = HashMap::new();
 74→
 75→    for (line_num, line) in content.lines().enumerate() {
 76→        let line = line.trim();
 77→
 78→        // Skip empty lines and comments
 79→        if line.is_empty() || line.starts_with('#') {
 80→            continue;
 81→        }
 82→
 83→        // Parse KEY=value
 84→        if let Some(eq_pos) = line.find('=') {
 85→            let key = line[..eq_pos].trim().to_string();
 86→            let mut value = line[eq_pos + 1..].trim().to_string();
 87→
 88→            // Remove surrounding quotes if present
 89→            if ((value.starts_with('"') && value.ends_with('"'))
 90→                || (value.starts_with('\'') && value.ends_with('\'')))
 91→                && value.len() >= 2
 92→            {
 93→                value = value[1..value.len() - 1].to_string();
 94→            }
 95→
 96→            env.insert(key, value);
 97→        } else {
 98→            return Err(BivvyError::ConfigParseError {
 99→                path: source_path.to_path_buf(),
100→                message: format!("Invalid line {}: {}", line_num + 1, line),
101→            });
102→        }
103→    }
104→
105→    Ok(env)
106→}
107→
108→/// Check if an environment variable name matches secret patterns.
109→///
110→/// Checks against both built-in `SECRET_PATTERNS` and any additional
111→/// patterns provided.
112→pub fn is_secret(name: &str, additional_patterns: &[String]) -> bool {
113→    let all_patterns: Vec<&str> = SECRET_PATTERNS
114→        .iter()
115→        .copied()
116→        .chain(additional_patterns.iter().map(|s| s.as_str()))
117→        .collect();
118→
119→    for pattern in all_patterns {
120→        if matches_pattern(name, pattern) {
121→            return true;
122→        }
123→    }
124→
125→    false
126→}
127→
128→/// Simple glob-style pattern matching (* matches any characters).
129→fn matches_pattern(name: &str, pattern: &str) -> bool {
130→    if pattern.starts_with('*') && pattern.ends_with('*') && pattern.len() >= 2 {
131→        // *MIDDLE* - contains
132→        let middle = &pattern[1..pattern.len() - 1];
133→        name.contains(middle)
134→    } else if let Some(suffix) = pattern.strip_prefix('*') {
135→        // *SUFFIX - ends with
136→        name.ends_with(suffix)
137→    } else if let Some(prefix) = pattern.strip_suffix('*') {
138→        // PREFIX* - starts with
139→        name.starts_with(prefix)
140→    } else {
141→        // Exact match
142→        name == pattern
143→    }
144→}
