 12→fn setup_project(config: &str) -> TempDir {
 13→    let temp = TempDir::new().unwrap();
 14→    let bivvy_dir = temp.path().join(".bivvy");
 15→    fs::create_dir_all(&bivvy_dir).unwrap();
 16→    fs::write(bivvy_dir.join("config.yml"), config).unwrap();
 17→    temp
