  1→//! JSON Schema generation for Bivvy configuration.
  2→//!
  3→//! This module generates a JSON Schema (Draft-07) for the Bivvy configuration
  4→//! file format, enabling IDE autocomplete and validation.
  5→
  6→use serde_json::{json, Value};
  7→
  8→/// Generates JSON Schema for Bivvy configuration.
  9→pub struct SchemaGenerator;
 10→
 11→impl SchemaGenerator {
 12→    /// Create a new schema generator.
 13→    pub fn new() -> Self {
 14→        Self
 15→    }
 16→
 17→    /// Generate the complete JSON Schema for bivvy.yml.
 18→    pub fn generate(&self) -> Value {
 19→        json!({
 20→            "$schema": "http://json-schema.org/draft-07/schema#",
 21→            "$id": "https://bivvy.dev/schemas/config.json",
 22→            "title": "Bivvy Configuration",
 23→            "description": "Configuration schema for Bivvy development environment setup",
 24→            "type": "object",
 25→            "properties": {
 26→                "app_name": {
 27→                    "type": "string",
 28→                    "description": "Name of the application"
 29→                },
 30→                "settings": self.settings_schema(),
 31→                "steps": self.steps_schema(),
 32→                "workflows": self.workflows_schema()
 33→            },
 34→            "additionalProperties": false
 35→        })
 36→    }
 37→
 38→    /// Generate schema for the settings object.
 39→    fn settings_schema(&self) -> Value {
 40→        json!({
 41→            "type": "object",
 42→            "description": "Global settings",
 43→            "properties": {
 44→                "default_output": {
 45→                    "type": "string",
 46→                    "enum": ["verbose", "quiet", "silent"],
 47→                    "default": "verbose",
 48→                    "description": "Default output verbosity"
 49→                },
 50→                "logging": {
 51→                    "type": "boolean",
 52→                    "default": false,
 53→                    "description": "Enable logging"
 54→                }
 55→            },
 56→            "additionalProperties": false
 57→        })
 58→    }
 59→
 60→    /// Generate schema for steps.
 61→    fn steps_schema(&self) -> Value {
 62→        json!({
 63→            "type": "object",
 64→            "description": "Step definitions",
 65→            "additionalProperties": {
 66→                "type": "object",
 67→                "properties": {
 68→                    "template": {
 69→                        "type": "string",
 70→                        "description": "Template to use for this step"
 71→                    },
 72→                    "command": {
 73→                        "type": "string",
 74→                        "description": "Command to execute (if not using template)"
 75→                    },
 76→                    "description": {
 77→                        "type": "string",
 78→                        "description": "Human-readable description"
 79→                    },
 80→                    "depends_on": {
 81→                        "type": "array",
 82→                        "items": { "type": "string" },
 83→                        "description": "Steps that must run before this one"
 84→                    },
 85→                    "completed_check": self.completed_check_schema(),
 86→                    "watches": {
 87→                        "type": "array",
 88→                        "items": { "type": "string" },
 89→                        "description": "Files to watch for changes"
 90→                    },
 91→                    "inputs": {
 92→                        "type": "object",
 93→                        "additionalProperties": true,
 94→                        "description": "Input values for the template"
 95→                    }
 96→                },
 97→                "additionalProperties": false
 98→            }
 99→        })
100→    }
101→
102→    /// Generate schema for completed_check.
103→    fn completed_check_schema(&self) -> Value {
104→        json!({
105→            "type": "object",
106→            "description": "How to check if step is complete",
107→            "properties": {
108→                "type": {
109→                    "type": "string",
110→                    "enum": ["file_exists", "command_succeeds", "marker"],
111→                    "description": "Type of completion check"
112→                },
113→                "path": {
114→                    "type": "string",
115→                    "description": "Path for file_exists check"
116→                },
117→                "command": {
118→                    "type": "string",
119→                    "description": "Command for command_succeeds check"
120→                }
121→            },
122→            "required": ["type"]
123→        })
124→    }
125→
126→    /// Generate schema for workflows.
127→    fn workflows_schema(&self) -> Value {
128→        json!({
129→            "type": "object",
130→            "description": "Workflow definitions",
131→            "additionalProperties": {
132→                "type": "object",
133→                "properties": {
134→                    "description": {
135→                        "type": "string",
136→                        "description": "Human-readable description"
137→                    },
138→                    "steps": {
139→                        "type": "array",
140→                        "items": { "type": "string" },
141→                        "description": "Steps to run in this workflow"
142→                    }
143→                },
144→                "required": ["steps"],
145→                "additionalProperties": false
146→            }
147→        })
148→    }
149→}
150→
151→impl Default for SchemaGenerator {
152→    fn default() -> Self {
153→        Self::new()
154→    }
155→}
