  1→//! Lint command implementation.
  2→//!
  3→//! The `bivvy lint` command validates configuration files using the lint rule system.
  4→
  5→use std::path::{Path, PathBuf};
  6→
  7→use crate::cli::args::LintArgs;
  8→use crate::config::{load_merged_config, ConfigPaths};
  9→use crate::error::{BivvyError, Result};
 10→use crate::lint::{
 11→    CircularRequirementDepRule, Fix, FixEngine, HumanFormatter, InstallTemplateMissingRule,
 12→    JsonFormatter, LintDiagnostic, LintFormatter, RuleRegistry, SarifFormatter,
 13→    ServiceRequirementWithoutHintRule, Severity, TemplateInputsRule, UndefinedTemplateRule,
 14→    UnknownRequirementRule,
 15→};
 16→use crate::registry::Registry;
 17→use crate::requirements::registry::RequirementRegistry;
 18→use crate::ui::{OutputMode, UserInterface};
 19→
 20→use super::dispatcher::{Command, CommandResult};
 21→
 22→/// The lint command implementation.
 23→pub struct LintCommand {
 24→    project_root: PathBuf,
 25→    args: LintArgs,
 26→}
 27→
 28→impl LintCommand {
 29→    /// Create a new lint command.
 30→    pub fn new(project_root: &Path, args: LintArgs) -> Self {
 31→        Self {
 32→            project_root: project_root.to_path_buf(),
 33→            args,
 34→        }
 35→    }
 36→
 37→    /// Get the project root path.
 38→    pub fn project_root(&self) -> &Path {
 39→        &self.project_root
 40→    }
 41→
 42→    /// Get the command arguments.
 43→    pub fn args(&self) -> &LintArgs {
 44→        &self.args
 45→    }
 46→
 47→    /// Run all lint rules and collect diagnostics.
 48→    fn run_rules(
 49→        &self,
 50→        registry: &RuleRegistry,
 51→        config: &crate::config::BivvyConfig,
 52→    ) -> Vec<LintDiagnostic> {
 53→        let mut diagnostics = Vec::new();
 54→        for rule in registry.iter() {
 55→            diagnostics.extend(rule.check(config));
 56→        }
 57→        diagnostics
 58→    }
 59→
 60→    /// Format diagnostics using the appropriate formatter.
 61→    fn format_output(&self, diagnostics: &[LintDiagnostic]) -> String {
 62→        let mut output = Vec::new();
 63→
 64→        match self.args.format.as_str() {
 65→            "json" => {
 66→                let formatter = JsonFormatter::new();
 67→                formatter.format(diagnostics, &mut output).ok();
 68→            }
 69→            "sarif" => {
 70→                let formatter = SarifFormatter::new("bivvy", env!("CARGO_PKG_VERSION"));
 71→                formatter.format(diagnostics, &mut output).ok();
 72→            }
 73→            _ => {
 74→                let formatter = HumanFormatter::new(true);
 75→                formatter.format(diagnostics, &mut output).ok();
 76→            }
 77→        }
 78→
 79→        String::from_utf8(output).unwrap_or_default()
 80→    }
 81→}
 82→
 83→impl Command for LintCommand {
 84→    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
 85→        // Check if config exists
 86→        let paths = ConfigPaths::discover(&self.project_root);
 87→        if !paths.has_project_config() {
 88→            ui.error("No configuration found. Run 'bivvy init' first.");
 89→            return Ok(CommandResult::failure(2));
 90→        }
 91→
 92→        // Load configuration
 93→        let config = match load_merged_config(&self.project_root) {
 94→            Ok(c) => c,
 95→            Err(BivvyError::ConfigParseError { path, message }) => {
 96→                ui.error(&format!("Parse error in {}: {}", path.display(), message));
 97→                return Ok(CommandResult::failure(1));
 98→            }
 99→            Err(e) => return Err(e),
100→        };
101→
102→        // Apply config default_output when no CLI flag was explicitly set
103→        if ui.output_mode() == OutputMode::Normal {
104→            ui.set_output_mode(config.settings.default_output.into());
105→        }
106→
107→        // Create rule registry with built-in rules
108→        let mut rule_registry = RuleRegistry::with_builtins();
109→
110→        // Add template-related rules if we can load the template registry
111→        let template_registry_result = if config.template_sources.is_empty() {
112→            Registry::new(Some(&self.project_root))
113→        } else {
114→            Registry::with_remote_sources(Some(&self.project_root), &config.template_sources)
115→        };
116→        if let Ok(template_registry) = template_registry_result {
117→            rule_registry.register(Box::new(UndefinedTemplateRule::new(
118→                template_registry.clone(),
119→            )));
120→            rule_registry.register(Box::new(TemplateInputsRule::new(template_registry)));
121→        }
122→
123→        // Add requirement-related rules
124→        // Each rule takes ownership of its own RequirementRegistry instance
125→        let make_req_registry = || RequirementRegistry::new().with_custom(&config.requirements);
126→        rule_registry.register(Box::new(UnknownRequirementRule::new(make_req_registry())));
127→        rule_registry.register(Box::new(CircularRequirementDepRule::new(
128→            make_req_registry(),
129→        )));
130→        rule_registry.register(Box::new(InstallTemplateMissingRule::new(
131→            make_req_registry(),
132→        )));
133→        rule_registry.register(Box::new(ServiceRequirementWithoutHintRule::new(
134→            make_req_registry(),
135→        )));
136→
137→        // Run all lint rules
138→        let mut diagnostics = self.run_rules(&rule_registry, &config);
139→
140→        // Apply fixes if requested
141→        if self.args.fix {
142→            let fixes: Vec<Fix> = diagnostics
143→                .iter()
144→                .filter_map(|d| {
145→                    // Only create fixes for diagnostics that have suggestions and spans
146→                    match (&d.suggestion, &d.span) {
147→                        (Some(suggestion), Some(span)) => Some(Fix {
148→                            file: span.file.clone(),
149→                            start: 0, // Would need actual byte offsets from marked_yaml
150→                            end: 0,
151→                            replacement: suggestion.clone(),
152→                        }),
153→                        _ => None,
154→                    }
155→                })
156→                .collect();
157→
158→            if !fixes.is_empty() {
159→                let engine = FixEngine::new();
160→                let result = engine.apply_fixes(&diagnostics, &fixes);
161→                if result.applied > 0 {
162→                    ui.success(&format!("Applied {} fix(es)", result.applied));
163→                    // Re-run rules after fixes
164→                    diagnostics = self.run_rules(&rule_registry, &config);
165→                }
166→            }
167→        }
168→
169→        // Check for errors based on strict mode
170→        let has_errors = diagnostics.iter().any(|d| d.severity == Severity::Error);
171→        let has_warnings = diagnostics.iter().any(|d| d.severity == Severity::Warning);
172→        let should_fail = has_errors || (self.args.strict && has_warnings);
173→
174→        if diagnostics.is_empty() {
175→            if self.args.format == "human" {
176→                ui.success("Configuration is valid!");
177→            } else {
178→                // For JSON/SARIF, still output the formatted result (empty diagnostics)
179→                let output = self.format_output(&diagnostics);
180→                ui.message(&output);
181→            }
182→            return Ok(CommandResult::success());
183→        }
184→
185→        // Output diagnostics in the requested format
186→        let output = self.format_output(&diagnostics);
187→
188→        // For human format, we need to write each line
189→        if self.args.format == "human" {
190→            for line in output.lines() {
191→                if line.starts_with("error") {
192→                    ui.error(line);
193→                } else if line.starts_with("warning") {
194→                    ui.warning(line);
195→                } else {
196→                    ui.message(line);
197→                }
198→            }
199→        } else {
200→            // For JSON/SARIF, output as-is
201→            ui.message(&output);
202→        }
203→
