```rust
/// Check for format conflicts (both .yml and .toml exist for the same config slot).
///
/// Returns a descriptive error if any conflicts are found.
pub fn validate_no_format_conflicts(project_root: &Path) -> Result<()> {
    let bivvy_dir = project_root.join(".bivvy");

    for base in &["config", "config.local"] {
        let toml_path = bivvy_dir.join(format!("{}.toml", base));
        let yml_path = bivvy_dir.join(format!("{}.yml", base));

        if toml_path.exists() && yml_path.exists() {
            return Err(BivvyError::ConfigValidationError {
                message: format!(
                    "Both {}.toml and {}.yml exist in {}. Remove one to avoid ambiguity.",
                    base, base, bivvy_dir.display()
                ),
            });
        }
    }

    // Also check user global
    if let Some(home) = dirs::home_dir() {
        let global_dir = home.join(".bivvy");
        let toml_path = global_dir.join("config.toml");
        let yml_path = global_dir.join("config.yml");
        if toml_path.exists() && yml_path.exists() {
            return Err(BivvyError::ConfigValidationError {
                message: format!(
                    "Both config.toml and config.yml exist in {}. Remove one to avoid ambiguity.",
                    global_dir.display()
                ),
            });
        }
    }

    Ok(())
}
```

