Current implementation at line 172 reads a file and always parses it as YAML. Change it to detect the format:

```rust
pub fn load_config_value(path: &Path) -> Result<serde_yaml::Value> {
    let content = fs::read_to_string(path).map_err(|e| {
        if e.kind() == std::io::ErrorKind::NotFound {
            BivvyError::ConfigNotFound {
                path: path.to_path_buf(),
            }
        } else {
            BivvyError::Io(e)
        }
    })?;

    let format = ConfigFormat::from_path(path).unwrap_or(ConfigFormat::Yaml);

    match format {
        ConfigFormat::Yaml => {
            serde_yaml::from_str(&content).map_err(|e| BivvyError::ConfigParseError {
                path: path.to_path_buf(),
                message: e.to_string(),
            })
        }
        ConfigFormat::Toml => toml_str_to_yaml_value(&content, path),
    }
}
```

The `unwrap_or(ConfigFormat::Yaml)` preserves backwards compatibility for paths without recognized extensions.

